// Pulls in the Rust types generated from ui/main_window.slint
// (this exposes the `MainWindow` struct, generated by slint-build in build.rs).
slint::include_modules!();

use std::{
    cell::RefCell,
    collections::HashSet,
    path::{Path, PathBuf},
    rc::Rc,
};

#[derive(Default)]
struct MediaData {
    browse: Vec<MediaEntry>,
    library: Vec<MediaEntry>,
    favorites: Vec<MediaEntry>,
    recent: Vec<MediaEntry>,
    history: Vec<MediaEntry>,
    playlist: Vec<MediaEntry>,
    active_playlist_position: Option<usize>,
    pending_capture: Option<PendingCapture>,
}

struct PendingCapture {
    video: PathBuf,
    thumbnail: PathBuf,
    next_step: std::time::Instant,
    requested: bool,
}

fn app_data_dir() -> PathBuf {
    std::env::var_os("LOCALAPPDATA")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
        .join("FluentPlayer")
}

fn load_preference(key: &str, fallback: bool) -> bool {
    let Ok(contents) = std::fs::read_to_string(app_data_dir().join("preferences.txt")) else {
        return fallback;
    };
    contents
        .lines()
        .find_map(|line| line.strip_prefix(&format!("{key}=")))
        .map(|value| value == "true")
        .unwrap_or(fallback)
}

fn persist_preferences(reduce_motion: bool, hardware_decoding: bool) {
    let folder = app_data_dir();
    if std::fs::create_dir_all(&folder).is_ok() {
        let _ = std::fs::write(
            folder.join("preferences.txt"),
            format!("reduce-motion={reduce_motion}\nhardware-decoding={hardware_decoding}\n"),
        );
    }
}

fn thumbnail_path(path: &Path) -> PathBuf {
    use std::hash::{Hash, Hasher};
    let mut hash = std::collections::hash_map::DefaultHasher::new();
    path.to_string_lossy().to_lowercase().hash(&mut hash);
    app_data_dir()
        .join("Thumbnails")
        .join(format!("{:016x}.png", hash.finish()))
}

fn is_video_path(path: &Path) -> bool {
    const VIDEO_EXTENSIONS: [&str; 15] = [
        "mp4", "mkv", "webm", "mov", "avi", "wmv", "m4v", "mpg", "mpeg", "ts", "m2ts", "3gp",
        "ogv", "flv", "vob",
    ];
    path.extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| {
            VIDEO_EXTENSIONS
                .iter()
                .any(|valid| extension.eq_ignore_ascii_case(valid))
        })
}

fn format_time(seconds: f64) -> String {
    let seconds = seconds.max(0.0) as u64;
    format!("{:02}:{:02}:{:02}", seconds / 3600, (seconds / 60) % 60, seconds % 60)
}

fn persist_recent(items: &[MediaEntry]) {
    let file = app_data_dir().join("recent.txt");
    if std::fs::create_dir_all(app_data_dir()).is_ok() {
        let content = items
            .iter()
            .map(|item| item.path.as_str())
            .collect::<Vec<_>>()
            .join("\n");
        let _ = std::fs::write(file, content);
    }
}

fn load_recent() -> Vec<MediaEntry> {
    let Ok(contents) = std::fs::read_to_string(app_data_dir().join("recent.txt")) else {
        return Vec::new();
    };
    contents
        .lines()
        .filter_map(|line| {
            let path = PathBuf::from(line);
            path.is_file().then(|| make_entry(&path))
        })
        .take(50)
        .collect()
}

fn make_entry(path: &Path) -> MediaEntry {
    let thumbnail = thumbnail_path(path);
    let thumbnail = if thumbnail.is_file() {
        slint::Image::load_from_path(&thumbnail).unwrap_or_default()
    } else {
        slint::Image::default()
    };
    MediaEntry {
        title: path
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| path.display().to_string())
            .into(),
        subtitle: path
            .parent()
            .map(|parent| parent.to_string_lossy().into_owned())
            .unwrap_or_default()
            .into(),
        path: path.to_string_lossy().into_owned().into(),
        thumbnail,
        playing: false,
    }
}

fn scan_folder(folder: &Path) -> Vec<MediaEntry> {
    const EXTENSIONS: [&str; 18] = [
        "mp4", "mkv", "webm", "mov", "avi", "wmv", "m4v", "mpg", "mpeg", "ts", "m2ts", "3gp",
        "ogv", "flv", "vob", "mp3", "flac", "wav",
    ];
    fn visit(folder: &Path, depth: usize, paths: &mut Vec<PathBuf>) {
        if paths.len() >= 500 || depth > 2 {
            return;
        }
        let Ok(entries) = std::fs::read_dir(folder) else {
            return;
        };
        for entry in entries.flatten() {
            if paths.len() >= 500 {
                break;
            }
            let path = entry.path();
            let Ok(kind) = entry.file_type() else {
                continue;
            };
            if kind.is_dir() {
                visit(&path, depth + 1, paths);
            } else if kind.is_file()
                && path
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| {
                        EXTENSIONS
                            .iter()
                            .any(|valid| extension.eq_ignore_ascii_case(valid))
                    })
            {
                paths.push(path);
            }
        }
    }
    let mut paths = Vec::new();
    visit(folder, 0, &mut paths);
    paths.sort_by_key(|path| {
        path.file_name()
            .map(|name| name.to_string_lossy().to_lowercase())
    });
    paths.iter().map(|path| make_entry(path)).collect()
}

fn publish_media(window: &MainWindow, data: &MediaData) {
    window.set_media_items(slint::ModelRc::from(std::rc::Rc::new(
        slint::VecModel::from(data.browse.clone()),
    )));
    window.set_library_items(slint::ModelRc::from(std::rc::Rc::new(
        slint::VecModel::from(data.library.clone()),
    )));
    window.set_favorite_items(slint::ModelRc::from(std::rc::Rc::new(
        slint::VecModel::from(data.favorites.clone()),
    )));
    window.set_recent_items(slint::ModelRc::from(std::rc::Rc::new(
        slint::VecModel::from(data.recent.clone()),
    )));
    window.set_history_items(slint::ModelRc::from(std::rc::Rc::new(
        slint::VecModel::from(data.history.clone()),
    )));
    window.set_playlist_items(slint::ModelRc::from(std::rc::Rc::new(
        slint::VecModel::from(data.playlist.clone()),
    )));
    window.set_activity_summary(
        format!(
            "{} videos in library  ·  {} favorites  ·  {} recently played",
            data.library.len(),
            data.favorites.len(),
            data.recent.len()
        )
        .into(),
    );
}

fn show_browse_folder(window: &MainWindow, media: &Rc<RefCell<MediaData>>, path: &Path) {
    if !path.is_dir() {
        window.set_notice(format!("Folder not found: {}", path.display()).into());
        window.set_current_page("Browse".into());
        return;
    }
    let entries = scan_folder(path);
    media.borrow_mut().browse = entries.clone();
    publish_media(window, &media.borrow());
    window.set_notice(format!("{} videos · {}", entries.len(), path.display()).into());
    window.set_current_page("Browse".into());
}

fn start_media(
    window: &MainWindow,
    player: &Rc<RefCell<Option<crate::player::MpvPlayer>>>,
    media: &Rc<RefCell<MediaData>>,
    path: &std::path::Path,
) -> anyhow::Result<String> {
    let mut player = player.borrow_mut();
    let created = player.is_none();
    if player.is_none() {
        *player = Some(crate::player::MpvPlayer::new(
            &window.window(),
            window.window().scale_factor(),
        )?);
    }
    let instance = player.as_mut().expect("player initialized above");
    if created && !window.get_hardware_decoding() {
        instance.toggle_hardware_decoding()?;
    }
    instance.open(path)?;
    instance.resize_surface(&window.window(), window.window().scale_factor());
    instance.show_surface(true);
    let name = path
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string());
    let mut entry = make_entry(path);
    entry.playing = true;
    {
        let mut media = media.borrow_mut();
        media.playlist.clear();
        media.playlist.push(entry.clone());
        media.active_playlist_position = Some(0);
        media.recent.retain(|item| item.path != entry.path);
        media.recent.insert(0, entry.clone());
        media.recent.truncate(50);
        media.history.retain(|item| item.path != entry.path);
        media.history.insert(0, entry);
        media.history.truncate(500);
        persist_recent(&media.recent);
        if is_video_path(path) {
            let thumbnail = thumbnail_path(path);
            let _ = std::fs::create_dir_all(thumbnail.parent().unwrap_or(Path::new(".")));
            let _ = std::fs::remove_file(&thumbnail);
            media.pending_capture = Some(PendingCapture {
                video: path.to_path_buf(),
                thumbnail,
                next_step: std::time::Instant::now() + std::time::Duration::from_millis(1200),
                requested: false,
            });
        } else {
            media.pending_capture = None;
        }
        publish_media(window, &media);
    }
    window.set_selected_media(name.clone().into());
    window.set_playback_paused(false);
    window.set_playback_progress(0.0);
    window.set_playback_duration(0.0);
    window.set_playback_time("00:00:00 / 00:00:00".into());
    window.set_playback_current_time("00:00:00".into());
    window.set_playback_total_time("00:00:00".into());
    window.set_playback_volume(player.as_ref().unwrap().volume() as f32);
    window.set_playback_volume_label(format!("{:.0}%", player.as_ref().unwrap().volume()).into());
    window.set_playback_speed_label(format!("{:.1}×", player.as_ref().unwrap().speed()).into());
    window.set_notice("Now playing".into());
    window.set_current_page("Player".into());
    Ok(name)
}

/// Connect the Slint window to native file dialogs and the mpv playback core.
pub fn run() -> anyhow::Result<()> {
    let window = MainWindow::new()?;
    window.set_reduce_motion(load_preference("reduce-motion", false));
    window.set_hardware_decoding(load_preference("hardware-decoding", true));
    let player = Rc::new(RefCell::new(None::<crate::player::MpvPlayer>));
    let mut initial_media = MediaData::default();
    initial_media.recent = load_recent();
    initial_media.history = initial_media.recent.clone();
    let media = Rc::new(RefCell::new(initial_media));
    publish_media(&window, &media.borrow());

    let file_window = window.as_weak();
    let file_player = player.clone();
    let file_media = media.clone();
    window.on_open_files(move || {
        if let Some(paths) = crate::platform::pick_media_files() {
            if let Some(window) = file_window.upgrade() {
                if let Some(first) = paths.first() {
                    if let Err(error) = start_media(&window, &file_player, &file_media, first) {
                        window.set_notice(error.to_string().into());
                    } else {
                        let mut data = file_media.borrow_mut();
                        for path in paths.iter().skip(1) {
                            if let Some(player) = file_player.borrow_mut().as_mut() {
                                if let Err(error) = player.append(path) {
                                    window.set_notice(error.to_string().into());
                                    break;
                                }
                            }
                            data.playlist.push(make_entry(path));
                        }
                        publish_media(&window, &data);
                    }
                }
            }
        }
    });

    let continue_window = window.as_weak();
    let continue_player = player.clone();
    let continue_media = media.clone();
    window.on_continue_media(move || {
        let Some(window) = continue_window.upgrade() else {
            return;
        };
        let result = continue_player.borrow_mut().as_mut().map(|player| {
            player.show_surface(true);
            player.resume()
        });
        match result {
            Some(Ok(())) => {
                window.set_playback_paused(false);
                window.set_current_page("Player".into());
                window.set_notice("Resumed playback".into());
            }
            Some(Err(error)) => window.set_notice(error.to_string().into()),
            None => {
                drop(continue_player.borrow());
                if let Some(path) = crate::platform::pick_media_file() {
                    if let Err(error) =
                        start_media(&window, &continue_player, &continue_media, &path)
                    {
                        window.set_notice(error.to_string().into());
                    }
                }
            }
        }
    });

    let home_player = player.clone();
    let home_window = window.as_weak();
    window.on_home_player(move || {
        if let Some(window) = home_window.upgrade() {
            if let Some(player) = home_player.borrow_mut().as_mut() {
                player.show_surface(false);
            }
            window.set_current_page("Home".into());
        }
    });

    let pause_player = player.clone();
    let pause_window = window.as_weak();
    window.on_pause_player(move || {
        if let Some(window) = pause_window.upgrade() {
            if let Some(player) = pause_player.borrow_mut().as_mut() {
                match player.toggle_pause() {
                    Ok(()) => {
                        window.set_playback_paused(!window.get_playback_paused());
                        window.set_notice("Playback toggled.".into());
                    }
                    Err(error) => window.set_notice(error.to_string().into()),
                }
            }
        }
    });

    let skip_back_window = window.as_weak();
    let skip_back_player = player.clone();
    window.on_skip_back_player(move || {
        if let Some(window) = skip_back_window.upgrade() {
            if let Some(player) = skip_back_player.borrow_mut().as_mut() {
                if let Err(error) = player.seek_relative(-10.0) {
                    window.set_notice(error.to_string().into());
                }
            }
        }
    });

    let skip_forward_window = window.as_weak();
    let skip_forward_player = player.clone();
    window.on_skip_forward_player(move || {
        if let Some(window) = skip_forward_window.upgrade() {
            if let Some(player) = skip_forward_player.borrow_mut().as_mut() {
                if let Err(error) = player.seek_relative(10.0) {
                    window.set_notice(error.to_string().into());
                }
            }
        }
    });

    let mute_window = window.as_weak();
    let mute_player = player.clone();
    window.on_toggle_mute_player(move || {
        if let Some(window) = mute_window.upgrade() {
            if let Some(player) = mute_player.borrow_mut().as_mut() {
                if let Err(error) = player.toggle_mute() {
                    window.set_notice(error.to_string().into());
                }
            }
        }
    });

    let captions_window = window.as_weak();
    let captions_player = player.clone();
    window.on_toggle_captions_player(move || {
        if let Some(window) = captions_window.upgrade() {
            if let Some(player) = captions_player.borrow_mut().as_mut() {
                if let Err(error) = player.toggle_subtitles() {
                    window.set_notice(error.to_string().into());
                }
            }
        }
    });

    let repeat_window = window.as_weak();
    let repeat_player = player.clone();
    window.on_toggle_repeat_player(move || {
        if let Some(window) = repeat_window.upgrade() {
            if let Some(player) = repeat_player.borrow_mut().as_mut() {
                if let Err(error) = player.toggle_repeat() {
                    window.set_notice(error.to_string().into());
                }
            }
        }
    });

    let recent_window = window.as_weak();
    let recent_player = player.clone();
    window.on_show_recent(move || {
        if let Some(window) = recent_window.upgrade() {
            if let Some(player) = recent_player.borrow_mut().as_mut() {
                player.show_surface(false);
            }
            window.set_current_page("Recent".into());
        }
    });

    let playlist_window = window.as_weak();
    let playlist_player = player.clone();
    window.on_show_playlist(move || {
        if let Some(window) = playlist_window.upgrade() {
            if let Some(player) = playlist_player.borrow_mut().as_mut() {
                player.show_surface(false);
            }
            window.set_current_page("Playlist".into());
        }
    });

    let queued_window = window.as_weak();
    let queued_player = player.clone();
    let queued_data = media.clone();
    window.on_play_queued(move |path| {
        let Some(window) = queued_window.upgrade() else { return; };
        let path = PathBuf::from(path.as_str());
        let position = queued_data.borrow().playlist.iter().position(|item| item.path == path.to_string_lossy());
        if let (Some(position), Some(player)) = (position, queued_player.borrow_mut().as_mut()) {
            if let Err(error) = player.play_index(position) { window.set_notice(error.to_string().into()); }
            else {
                player.show_surface(true);
                let mut data = queued_data.borrow_mut();
                data.active_playlist_position = Some(position);
                for (index, item) in data.playlist.iter_mut().enumerate() { item.playing = index == position; }
                publish_media(&window, &data);
                window.set_current_page("Player".into());
            }
        }
    });

    let next_window = window.as_weak(); let next_player = player.clone();
    window.on_next_player(move || { if let Some(window) = next_window.upgrade() { if let Some(player) = next_player.borrow_mut().as_mut() { if let Err(e) = player.play_next() { window.set_notice(e.to_string().into()); } } } });
    let prev_window = window.as_weak(); let prev_player = player.clone();
    window.on_previous_player(move || { if let Some(window) = prev_window.upgrade() { if let Some(player) = prev_player.borrow_mut().as_mut() { if let Err(e) = player.play_previous() { window.set_notice(e.to_string().into()); } } } });

    let frame_window = window.as_weak(); let frame_player = player.clone();
    window.on_step_frame_player(move || { if let Some(w)=frame_window.upgrade() { if let Some(p)=frame_player.borrow_mut().as_mut() { if let Err(e)=p.step_frame() { w.set_notice(e.to_string().into()); } } } });
    let ab_window = window.as_weak(); let ab_player = player.clone();
    window.on_toggle_ab_loop_player(move || { if let Some(w)=ab_window.upgrade() { if let Some(p)=ab_player.borrow_mut().as_mut() { if let Err(e)=p.toggle_ab_loop() { w.set_notice(e.to_string().into()); } else { w.set_notice("A–B loop marker updated".into()); } } } });
    let fullscreen_window = window.as_weak();
    window.on_toggle_fullscreen_player(move || {
        if let Some(w) = fullscreen_window.upgrade() {
            let fullscreen = !w.get_fullscreen();
            w.window().set_fullscreen(fullscreen);
            w.set_fullscreen(fullscreen);
        }
    });

    let volume_set_window = window.as_weak();
    let volume_set_player = player.clone();
    window.on_set_volume_player(move |value| {
        if let Some(w) = volume_set_window.upgrade() {
            if let Some(p) = volume_set_player.borrow_mut().as_mut() {
                match p.set_volume(value as f64) {
                    Ok(()) => {
                        let volume = p.volume() as f32;
                        w.set_playback_volume(volume);
                        w.set_playback_volume_label(format!("{volume:.0}%").into());
                    }
                    Err(e) => w.set_notice(e.to_string().into()),
                }
            }
        }
    });
    let pip_window = window.as_weak();
    let pip_player = player.clone();
    window.on_picture_in_picture_player(move || {
        if let Some(w) = pip_window.upgrade() {
            let enabled = !w.get_pip_mode();
            w.set_pip_mode(enabled);
            if enabled {
                w.window().set_maximized(false);
                w.window().set_size(slint::LogicalSize::new(480.0, 300.0));
            } else {
                w.window().set_size(slint::LogicalSize::new(1280.0, 700.0));
            }
            if let Some(p) = pip_player.borrow_mut().as_mut() { p.show_surface(true); }
            w.set_current_page("Player".into());
        }
    });
    let settings_window = window.as_weak();
    let settings_player = player.clone();
    window.on_show_settings_player(move || {
        if let Some(w) = settings_window.upgrade() {
            if let Some(p) = settings_player.borrow_mut().as_mut() { p.show_surface(false); }
            w.set_current_page("Settings".into());
        }
    });
    let minimize_window = window.as_weak();
    window.on_minimize_window_player(move || {
        if let Some(w) = minimize_window.upgrade() { w.window().set_minimized(true); }
    });
    let maximize_window = window.as_weak();
    window.on_maximize_window_player(move || {
        if let Some(w) = maximize_window.upgrade() {
            let maximized = !w.get_window_maximized();
            w.window().set_maximized(maximized);
            w.set_window_maximized(maximized);
        }
    });
    let close_window = window.as_weak();
    window.on_close_window_player(move || {
        if let Some(w) = close_window.upgrade() { let _ = w.window().hide(); }
    });

    let volume_down_window = window.as_weak(); let volume_down_player = player.clone();
    window.on_volume_down_player(move || { if let Some(window) = volume_down_window.upgrade() { if let Some(player) = volume_down_player.borrow_mut().as_mut() { let v=(player.volume()-5.0).max(0.0); if let Err(e)=player.set_volume(v) { window.set_notice(e.to_string().into()); } else { window.set_playback_volume_label(format!("{v:.0}%").into()); } } } });
    let volume_up_window = window.as_weak(); let volume_up_player = player.clone();
    window.on_volume_up_player(move || { if let Some(window) = volume_up_window.upgrade() { if let Some(player) = volume_up_player.borrow_mut().as_mut() { let v=(player.volume()+5.0).min(200.0); if let Err(e)=player.set_volume(v) { window.set_notice(e.to_string().into()); } else { window.set_playback_volume_label(format!("{v:.0}%").into()); } } } });
    let speed_down_window = window.as_weak(); let speed_down_player = player.clone();
    window.on_speed_down_player(move || { if let Some(window) = speed_down_window.upgrade() { if let Some(player) = speed_down_player.borrow_mut().as_mut() { let v=(player.speed()-0.25).max(0.25); if let Err(e)=player.set_speed(v) { window.set_notice(e.to_string().into()); } else { window.set_playback_speed_label(format!("{v:.2}×").into()); } } } });
    let speed_up_window = window.as_weak(); let speed_up_player = player.clone();
    window.on_speed_up_player(move || { if let Some(window) = speed_up_window.upgrade() { if let Some(player) = speed_up_player.borrow_mut().as_mut() { let v=(player.speed()+0.25).min(4.0); if let Err(e)=player.set_speed(v) { window.set_notice(e.to_string().into()); } else { window.set_playback_speed_label(format!("{v:.2}×").into()); } } } });
    let audio_window=window.as_weak(); let audio_player=player.clone();
    window.on_cycle_audio_player(move || { if let Some(w)=audio_window.upgrade() { if let Some(p)=audio_player.borrow_mut().as_mut() { if let Err(e)=p.cycle_audio_track() { w.set_notice(e.to_string().into()); } } } });
    let sub_window=window.as_weak(); let sub_player=player.clone();
    window.on_cycle_subtitle_player(move || { if let Some(w)=sub_window.upgrade() { if let Some(p)=sub_player.borrow_mut().as_mut() { if let Err(e)=p.cycle_subtitle_track() { w.set_notice(e.to_string().into()); } } } });
    let hw_window=window.as_weak(); let hw_player=player.clone();
    window.on_toggle_hardware_decoding_player(move || {
        let Some(w) = hw_window.upgrade() else { return; };
        let enabled = if let Some(p) = hw_player.borrow_mut().as_mut() {
            match p.toggle_hardware_decoding() {
                Ok(enabled) => enabled,
                Err(e) => { w.set_notice(e.to_string().into()); return; }
            }
        } else {
            !w.get_hardware_decoding()
        };
        w.set_hardware_decoding(enabled);
        persist_preferences(w.get_reduce_motion(), enabled);
    });
    let loop_window=window.as_weak(); let loop_player=player.clone();
    window.on_toggle_playlist_repeat_player(move || { if let Some(w)=loop_window.upgrade() { if let Some(p)=loop_player.borrow_mut().as_mut() { if let Err(e)=p.toggle_playlist_repeat() { w.set_notice(e.to_string().into()); } } } });

    let motion_window = window.as_weak();
    window.on_toggle_reduced_motion(move || {
        if let Some(w) = motion_window.upgrade() {
            let enabled = !w.get_reduce_motion();
            w.set_reduce_motion(enabled);
            persist_preferences(enabled, w.get_hardware_decoding());
        }
    });

    let reset_window = window.as_weak();
    let reset_player = player.clone();
    window.on_reset_video_player(move || {
        if let Some(w) = reset_window.upgrade() {
            if let Some(p) = reset_player.borrow_mut().as_mut() {
                if let Err(e) = p.reset_video_adjustments() { w.set_notice(e.to_string().into()); }
                else { w.set_notice("Video adjustments reset".into()); }
            } else { w.set_notice("Open media before resetting video adjustments".into()); }
        }
    });

    let adjust_window = window.as_weak();
    let adjust_player = player.clone();
    window.on_adjust_video_player(move |property, delta| {
        if let Some(w) = adjust_window.upgrade() {
            if let Some(p) = adjust_player.borrow_mut().as_mut() {
                if let Err(e) = p.adjust_video_property(property.as_str(), delta as f64) {
                    w.set_notice(e.to_string().into());
                }
            } else {
                w.set_notice("Open media before adjusting the picture".into());
            }
        }
    });

    let screenshot_window = window.as_weak();
    let screenshot_player = player.clone();
    window.on_screenshot_player(move || {
        if let Some(w) = screenshot_window.upgrade() {
            let folder = app_data_dir().join("Screenshots");
            let result = std::fs::create_dir_all(&folder).map_err(anyhow::Error::from).and_then(|_| {
                let stamp = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_secs();
                screenshot_player.borrow_mut().as_mut()
                    .ok_or_else(|| anyhow::anyhow!("Open media before taking a screenshot"))?
                    .screenshot(&folder.join(format!("fluent-{stamp}.png")))
            });
            match result {
                Ok(()) => w.set_notice(format!("Screenshot saved in {}", folder.display()).into()),
                Err(e) => w.set_notice(e.to_string().into()),
            }
        }
    });

    let seek_window = window.as_weak();
    let seek_player = player.clone();
    window.on_seek_player(move |seconds| {
        if let Some(window) = seek_window.upgrade() {
            if let Some(player) = seek_player.borrow_mut().as_mut() {
                if let Err(error) = player.seek_to(seconds as f64) {
                    window.set_notice(error.to_string().into());
                }
            }
        }
    });

    let open_media_window = window.as_weak();
    let open_media_player = player.clone();
    let open_media_data = media.clone();
    window.on_open_media(move |path| {
        let Some(window) = open_media_window.upgrade() else {
            return;
        };
        if let Err(error) = start_media(
            &window,
            &open_media_player,
            &open_media_data,
            Path::new(path.as_str()),
        ) {
            window.set_notice(error.to_string().into());
        }
    });

    let favorite_window = window.as_weak();
    let favorite_data = media.clone();
    window.on_toggle_favorite(move |path| {
        let Some(window) = favorite_window.upgrade() else {
            return;
        };
        let mut data = favorite_data.borrow_mut();
        if let Some(index) = data.favorites.iter().position(|item| item.path == path) {
            data.favorites.remove(index);
        } else if let Some(item) = data
            .browse
            .iter()
            .chain(data.library.iter())
            .chain(data.recent.iter())
            .find(|item| item.path == path)
            .cloned()
        {
            data.favorites.push(item);
        }
        publish_media(&window, &data);
    });

    let place_window = window.as_weak();
    let place_media = media.clone();
    window.on_open_place(move |place| {
        let Some(window) = place_window.upgrade() else {
            return;
        };
        let profile = std::env::var_os("USERPROFILE")
            .map(PathBuf::from)
            .unwrap_or_default();
        let path = match place.as_str() {
            "Home" => profile.clone(),
            "Videos" => profile.join("Videos"),
            "Music" => profile.join("Music"),
            "Downloads" => profile.join("Downloads"),
            "C:\\" => PathBuf::from("C:\\"),
            "D:\\" => PathBuf::from("D:\\"),
            _ => profile,
        };
        show_browse_folder(&window, &place_media, &path);
    });

    let folder_window = window.as_weak();
    let folder_data = media.clone();
    window.on_open_folder(move || {
        if let Some(path) = crate::platform::pick_media_folder() {
            if let Some(window) = folder_window.upgrade() {
                show_browse_folder(&window, &folder_data, &path);
            }
        }
    });

    let library_window = window.as_weak();
    let library_data = media.clone();
    window.on_add_library_folder(move || {
        if let Some(path) = crate::platform::pick_media_folder() {
            if let Some(window) = library_window.upgrade() {
                let name = path
                    .file_name()
                    .map(|name| name.to_string_lossy().into_owned())
                    .unwrap_or_else(|| path.display().to_string());
                let entries = scan_folder(&path);
                {
                    let mut data = library_data.borrow_mut();
                    let mut seen: HashSet<String> = data
                        .library
                        .iter()
                        .map(|item| item.path.to_string())
                        .collect();
                    data.library.extend(
                        entries
                            .iter()
                            .filter(|item| seen.insert(item.path.to_string()))
                            .cloned(),
                    );
                    publish_media(&window, &data);
                }
                window.set_notice(format!("Added {} videos from {name}", entries.len()).into());
                window.set_current_page("Library".into());
            }
        }
    });

    let resize_window = window.as_weak();
    let resize_player = player.clone();
    let resize_media = media.clone();
    let timer = slint::Timer::default();
    timer.start(
        slint::TimerMode::Repeated,
        std::time::Duration::from_millis(250),
        move || {
            if let (Some(window), Some(player)) =
                (resize_window.upgrade(), resize_player.borrow_mut().as_mut())
            {
                player.resize_surface(&window.window(), window.window().scale_factor());
                let (position, duration) = player.playback_times();
                if duration > 0.0 {
                    window.set_playback_duration(duration as f32);
                    window.set_playback_progress((position / duration).clamp(0.0, 1.0) as f32);
                    window.set_playback_current_time(format_time(position).into());
                    window.set_playback_total_time(format_time(duration).into());
                    window.set_playback_time(
                        format!("{} / {}", format_time(position), format_time(duration)).into(),
                    );
                }
                window.set_playback_volume(player.volume() as f32);
                let mut media = resize_media.borrow_mut();
                let playlist_position = player.playlist_position();
                if playlist_position != media.active_playlist_position {
                    media.active_playlist_position = playlist_position;
                    for (index, item) in media.playlist.iter_mut().enumerate() {
                        item.playing = Some(index) == playlist_position;
                    }
                    publish_media(&window, &media);
                }
                if let Some(pending) = media.pending_capture.as_mut() {
                    if std::time::Instant::now() >= pending.next_step {
                        if !pending.requested {
                            if player.screenshot(&pending.thumbnail).is_ok() {
                                pending.requested = true;
                                pending.next_step = std::time::Instant::now()
                                    + std::time::Duration::from_millis(800);
                            } else {
                                pending.next_step =
                                    std::time::Instant::now() + std::time::Duration::from_secs(2);
                            }
                        } else if pending.thumbnail.is_file() {
                            let video = pending.video.to_string_lossy().to_string();
                            let image = slint::Image::load_from_path(&pending.thumbnail)
                                .unwrap_or_default();
                            for entry in &mut media.recent {
                                if entry.path == video {
                                    entry.thumbnail = image.clone();
                                }
                            }
                            for entry in &mut media.history {
                                if entry.path == video {
                                    entry.thumbnail = image.clone();
                                }
                            }
                            media.pending_capture = None;
                            publish_media(&window, &media);
                        } else {
                            pending.next_step =
                                std::time::Instant::now() + std::time::Duration::from_millis(500);
                        }
                    }
                }
            }
        },
    );

    window.run()?;
    Ok(())
}
